fn lm_193(
    mut txt: Tpl::Text,
    items: &metamodelica::List<metamodelica::Ref<Absyn::ForIterator>>,
    mut a_preText: Tpl::Text,
) -> Result<(Tpl::Text, Tpl::Text)> {
    for lstElt_193 in items {
        ::match_deref::match_deref! { match lstElt_193 {
            i_i => {
                (txt, a_preText) = dumpForIterator(txt, a_preText, i_i)?;
                txt = Tpl::nextIter(txt)?;
            }
            _ => return Err("lm_193: no case matched"),
        } }
    }
    Ok((txt, a_preText))
}

pub fn dumpForIterators(
    mut txt: Tpl::Text,
    mut a_preText: Tpl::Text,
    a_iters: &metamodelica::List<metamodelica::Ref<Absyn::ForIterator>>,
) -> Result<(Tpl::Text, Tpl::Text)> {
    let mut out_txt;
    let mut out_a_preText;
    out_txt = Tpl::pushIter(
        txt,
        metamodelica::Ref::new(Tpl::IterOptions {
            startIndex0: 0,
            empty: None,
            separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
                value: literal!(", "),
            })),
            alignNum: 0,
            alignOfset: 0,
            alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
            wrapWidth: 0,
            wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
        }),
    )?;
    (out_txt, out_a_preText) = lm_193(out_txt, a_iters, a_preText)?;
    out_txt = Tpl::popIter(out_txt)?;
    Ok((out_txt, out_a_preText))
}

