fn fun_197(
    mut in_txt: Tpl::Text,
    in_a_iterator: &metamodelica::Ref<Absyn::ForIterator>,
    mut in_a_preText: Tpl::Text,
) -> Result<(Tpl::Text, Tpl::Text)> {
    ::match_deref::match_deref! { match in_a_iterator {
        Deref @ Absyn::ForIterator { guardExp: i_guardExp, range: i_range, name: i_name, .. } => {
            let mut txt = in_txt;
            let mut a_preText = in_a_preText;
            let mut l_ge;
            let mut l_re;
            let mut ret_2;
            (l_ge, a_preText) = fun_195((*Tpl::emptyTxt).clone(), i_guardExp, a_preText)?;
            (l_re, a_preText) = fun_196((*Tpl::emptyTxt).clone(), i_range, a_preText)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("ITERATOR(\"") }))?;
            ret_2 = Util::escapeModelicaStringToJLString(i_name.clone())?;
            txt = Tpl::writeStr(txt, ret_2)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("\", ") }))?;
            txt = Tpl::writeText(txt, l_ge)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(", ") }))?;
            txt = Tpl::writeText(txt, l_re)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(")") }))?;
            Ok((txt, a_preText))
        }
        _ => {
            let mut txt = in_txt;
            let mut a_preText = in_a_preText;
            Ok((txt, a_preText))
        }
        _ => Err("fun_197: no case matched"),
    } }
}

